import com.lc.billion.icefire.game.biz.dao.mongo.root.ServerInfoDao
import com.lc.billion.icefire.game.biz.service.impl.activity.handler.migrate.MigrateActivityHandler
var serverInfoDao = Application.getBean(ServerInfoDao.class);
var configCenter = Application.getConfigCenter();
for (var s : Application.getAllServerIds()) {
var data = serverInfoDao.findById(s);
if (data == null ) {
data = serverInfoDao.create(s, configCenter.getOpenTimeMs(s));
} else {
}
}
var handler =Application.getBean(MigrateActivityHandler.class);
handler.flushRoleToRedis();
return '1';
